//! 🔎️ Borrowed native domain census admits frontier backing and counts literal rows before copies.
use super::*;
pub(super) struct Counts{pub rows:usize,pub nodes:usize}
fn add(count:&mut Counts,rows:usize,maximum:usize)->Result<(),ValueError>{count.rows=count.rows.checked_add(rows).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"native projection row census overflow"))?;if count.rows>maximum{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"native projection rows exceed caller ceiling"))}Ok(())}
fn forest<T>(roots:&[T],children:for<'a> fn(&'a T)->&'a[T],c:&mut NativeEncodeControl<'_>,count:&mut Counts,maximum:usize)->Result<(),ValueError>{c.scoped_stage(|c|{add(count,roots.len(),maximum)?;c.begin_stage(0)?;let mut pending=c.allocate_vec::<std::slice::Iter<'_,T>>(1)?;pending.push(roots.iter());while !pending.is_empty(){let Some(value)=pending.last_mut().unwrap().next()else{pending.pop();continue};let children=children(value);add(count,1,maximum)?;add(count,children.len(),maximum)?;count.nodes=count.nodes.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"native value census overflow"))?;c.step()?;if !children.is_empty(){if pending.len()==pending.capacity(){let capacity=pending.capacity().checked_mul(2).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"native borrowed census frontier overflow"))?;let mut next=c.allocate_vec(capacity)?;c.scoped_stage(|c|{c.begin_stage(pending.len())?;for value in std::mem::take(&mut pending){next.push(value);c.step()?;}Ok::<_,ValueError>(())})?;pending=next;}pending.push(children.iter());}}Ok(())})}

fn children(value:&IfcValue)->&[IfcValue]{match value{IfcValue::Aggregate(values)|IfcValue::TypedValue{items:values,..}=>values,_=>&[]}}
pub(super) fn group(values:&[IfcValue],c:&mut NativeEncodeControl<'_>)->Result<usize,ValueError>{let mut count=Counts{rows:0,nodes:0};forest(values,children,c,&mut count,usize::MAX)?;Ok(count.nodes)}
pub(super) fn measure(value:&IfcSnapshot,c:&mut NativeEncodeControl<'_>,maximum:usize)->Result<Counts,ValueError>{let mut count=Counts{rows:2,nodes:0};add(&mut count,0,maximum)?;for values in [&value.header.file_description,&value.header.file_name,&value.header.file_schema]{forest(values,children,c,&mut count,maximum)?;}add(&mut count,value.entities.len(),maximum)?;c.scoped_stage(|c|{c.begin_stage(value.entities.len())?;for value in &value.entities{forest(&value.args,children,c,&mut count,maximum)?;add(&mut count,value.complex.len(),maximum)?;c.scoped_stage(|c|{c.begin_stage(value.complex.len())?;for value in &value.complex{forest(&value.args,children,c,&mut count,maximum)?;c.step()?;}Ok::<_,ValueError>(())})?;c.step()?;}Ok::<_,ValueError>(())})?;Ok(count)}
